mapper.select:
SELECT b.id AS id, c.id AS cameraId, c.name AS cameraName, b.track_id AS trackId, p.id AS presetPointId, p.pan_position AS panPosition, p.tilt_position AS tiltPosition, p.zoom AS zoom, p.small_range AS smallRange, p.wide_range AS wideRange FROM ballmachine b JOIN camera c ON b.camera_id = c.id JOIN preset_point p ON b.preset_point_id = p.id
and camera_id = #{cameraId}
and track_id = #{trackId}
ORDER BY c.id, b.track_id;
